-- === BƯỚC 1: KHỞI TẠO CẤU TRÚC BẢNG (SCHEMA DDL) ===
-- Bảng Người dùng và Phân quyền RBAC
CREATE TABLE IF NOT EXISTS users (
  id TEXT PRIMARY KEY,
  email TEXT UNIQUE NOT NULL,
  role TEXT NOT NULL CHECK(role IN ('admin', 'editor', 'reviewer')),
  created_at TEXT NOT NULL,
  updated_at TEXT NOT NULL
);

-- Bảng Bản nháp làm việc cho 8 phân hệ
CREATE TABLE IF NOT EXISTS drafts (
  module_key TEXT PRIMARY KEY,
  data_json TEXT NOT NULL,
  revision_hash TEXT NOT NULL,
  updated_by TEXT NOT NULL,
  updated_at TEXT NOT NULL
);

-- Bảng Lịch sử Phiên bản (Revisions) chống ghi đè và hỗ trợ khôi phục
CREATE TABLE IF NOT EXISTS revisions (
  id TEXT PRIMARY KEY,
  module_key TEXT NOT NULL,
  version INTEGER NOT NULL,
  data_json TEXT NOT NULL,
  revision_hash TEXT NOT NULL,
  created_by TEXT NOT NULL,
  created_at TEXT NOT NULL,
  comment TEXT
);

CREATE INDEX IF NOT EXISTS idx_revisions_module ON revisions(module_key, version DESC);

-- Bảng Yêu cầu và Trạng thái Xuất bản (Publications)
CREATE TABLE IF NOT EXISTS publications (
  id TEXT PRIMARY KEY,
  snapshot_json TEXT NOT NULL,
  status TEXT NOT NULL CHECK(status IN ('draft', 'pending_review', 'approved', 'published', 'rolled_back')),
  requested_by TEXT NOT NULL,
  approved_by TEXT,
  second_reviewer TEXT,
  published_at TEXT,
  git_ref TEXT,
  deploy_status TEXT NOT NULL DEFAULT 'unknown',
  error_message TEXT,
  idempotency_key TEXT UNIQUE,
  deployment_verified_at TEXT,
  created_at TEXT NOT NULL
);

-- Bảng Nhật ký Kiểm toán (Audit Logs)
CREATE TABLE IF NOT EXISTS audit_logs (
  id TEXT PRIMARY KEY,
  user_email TEXT NOT NULL,
  action TEXT NOT NULL,
  module_key TEXT NOT NULL,
  details_json TEXT NOT NULL,
  ip_address TEXT,
  created_at TEXT NOT NULL
);

CREATE INDEX IF NOT EXISTS idx_audit_created ON audit_logs(created_at DESC);

-- Bảng Quản lý Tệp Đa phương tiện và Ảnh (Media Assets)
CREATE TABLE IF NOT EXISTS media_assets (
  id TEXT PRIMARY KEY,
  filename TEXT NOT NULL,
  content_type TEXT NOT NULL,
  size_bytes INTEGER NOT NULL,
  r2_key TEXT NOT NULL,
  status TEXT NOT NULL CHECK(status IN ('pending', 'approved', 'rejected')),
  alt TEXT NOT NULL,
  caption TEXT,
  credit_name TEXT,
  credit_url TEXT,
  source TEXT,
  is_illustration INTEGER NOT NULL DEFAULT 1,
  focal_x INTEGER DEFAULT 50,
  focal_y INTEGER DEFAULT 50,
  created_by TEXT NOT NULL,
  created_at TEXT NOT NULL
);

-- === BƯỚC 2: KHỞI TẠO NGƯỜI DÙNG QUẢN TRỊ VÀ DUYỆT (RBAC) ===

-- === BƯỚC 3: KHỞI TẠO BẢN NHÁP VÀ PHIÊN BẢN CƠ SỞ (CANONICAL DRAFTS & REVISIONS) ===
INSERT OR IGNORE INTO drafts (module_key, data_json, revision_hash, updated_by, updated_at) VALUES ('project', '{"slug":"mang-theo-mot-net-ve","title":"Mang Theo Một Nét Vẽ","slogan":"Một buổi chơi phù hợp, một món quà đúng nhu cầu.","summary":"Bảy sinh viên Đại học FPT Hà Nội sẽ tổ chức một buổi vui chơi sáng tạo cho các em tại Mái ấm Thánh Tâm Xuy Xá, và gây quỹ để tặng những vật phẩm Mái ấm đang cần.","location":"Mái ấm Thánh Tâm Xuy Xá (Mỹ Đức, Hà Nội) & Campus FPT Hòa Lạc","executionStatus":"in_progress","statusNotice":"Đang triển khai · tuần 1","previewNotice":"Bản xem trước — nội dung theo đề xuất Final, chờ xác nhận.","activities":[{"id":"chuon-chuon-tre","title":"Chuồn chuồn tre và vẽ tranh","description":"Trang trí những cánh chuồn chuồn tre thăng bằng và vẽ tranh tự do với màu sắc theo sở thích.","badge":"Góc tạo hình","note":"Người tham gia có quyền lựa chọn vẽ tranh, trang trí, quan sát hoặc nghỉ ngơi."},{"id":"to-tuong","title":"Tô tượng sắc màu","description":"Thỏa sức phối màu trên các mẫu tượng thạch cao đa dạng hình dáng và kích cỡ (10 cm).","badge":"Góc tô màu","note":"Hoạt động vui chơi trải nghiệm tại chỗ, không gắn với sản phẩm gây quỹ."},{"id":"hat-cung-nhau","title":"Hát cùng nhau","description":"Không gian văn nghệ kết nối, cùng hòa giọng trong những giai điệu thiếu nhi gần gũi.","badge":"Góc âm nhạc","note":"Tạo không khí ấm áp, vui tươi và không áp lực biểu diễn."},{"id":"tro-choi-nhe","title":"Trò chơi tương tác nhẹ","description":"Các trò chơi tương tác vừa sức: bowling mini, chuyền bóng nhẹ nhàng và thẻ màu ghép hình.","badge":"Góc vận động","note":"Mỗi em nhỏ tự quyết định mức độ tham gia phù hợp thể trạng."}],"plannedStages":[{"step":"01","title":"Xác nhận và chuẩn bị","description":"Thống nhất với Mái ấm về lịch, hoạt động, vật liệu và danh mục quà; chuẩn bị đạo cụ an toàn."},{"step":"02","title":"Gây quỹ","description":"Tiếp nhận ủng hộ qua chuyển khoản và dự kiến bán quà lưu niệm. Hai nguồn được ghi riêng; khoản ủng hộ được công bố sau đối soát."},{"step":"03","title":"Buổi chơi tại Mái ấm","description":"14:00 Thứ Bảy 24/10/2026 (dự kiến). Bốn góc hoạt động, có hai lần nghỉ; có thể rút ngắn theo ý Mái ấm."},{"step":"04","title":"Đối soát và trao quà","description":"14:00 Thứ Bảy 31/10/2026 (dự kiến). Chốt quỹ, mua vật phẩm theo danh mục Mái ấm xác nhận và trao tặng."}],"needs":[{"title":"Một buổi chơi linh hoạt","description":"Có thời gian nghỉ và nhiều cách tham gia, vì các em ở nhiều độ tuổi và mức hỗ trợ khác nhau."},{"title":"Mái ấm giữ quyền quyết định","description":"Về số người tham gia, vật liệu, hình ảnh và danh mục hỗ trợ."},{"title":"Hỗ trợ thiết thực, minh bạch","description":"Chuyển nguồn quỹ thành hiện vật đúng danh mục Mái ấm xác nhận, có chứng từ và biên bản."}],"safetyPractices":["Chuồn chuồn mài nhẵn, màu gốc nước, tượng không cạnh nhọn.","Chia nhóm nhỏ theo lượt, luôn có góc nghỉ.","Trò chơi vận động nhẹ, có thể chơi khi ngồi, không loại người chơi.","Chỉ ghi hình trong phạm vi Mái ấm cho phép."],"progress":{"currentWeek":1,"totalWeeks":5,"updatedAt":"2026-10-09","currentStageIndex":0},"plannedSessions":[{"id":"buoi-choi","title":"Buổi chơi tại Mái ấm","date":"2026-10-24","time":"14:00","weekday":"Thứ Bảy","description":"Bốn góc hoạt động, khoảng 180 phút, có hai lần nghỉ."},{"id":"trao-qua","title":"Gặp lại và trao quà","date":"2026-10-31","time":"14:00","weekday":"Thứ Bảy","description":"Trao vật phẩm theo danh mục Mái ấm xác nhận, khoảng 30–45 phút."}],"contacts":{"status":"confirmed","people":[{"name":"Nguyễn Chí Trung","role":"Trưởng dự án","phone":"0984 441 726","phoneE164":"+84984441726"},{"name":"Lê Tuấn Anh","role":"Đại diện đối ngoại","phone":"0343 999 199","phoneE164":"+84343999199"}],"fanpageUrl":"https://www.facebook.com/mangtheomotnetve","sourceRef":"supplement-c07:muc-6","updatedAt":"2026-10-09"}}', 'a18c74c3019df5ed983c288cbbefa731b084c7812fd36962efd10c1589898a89', 'system-bootstrap@internal', '2026-10-13T00:00:00.000Z');
