onations":[],"firstSigner":null,"secondSigner":null}', 'ea550350f6ab52f523bbada59d748ecfc1032658723d9bd2b05cfd55c043c451', 'system-bootstrap@internal', '2026-10-13T00:00:00.000Z', 'Phiên bản khởi tạo từ nguồn chuẩn tắc (Bootstrap)');
INSERT OR IGNORE INTO drafts (module_key, data_json, revision_hash, updated_by, updated_at) VALUES ('team', '{"info":{"name":"Lăng Kính","description":"Lăng Kính là nhóm gồm 7 sinh viên lớp AI2015, học phần SSG105 (Kỹ năng làm việc nhóm), Đại học FPT Hà Nội. Nhóm xây dựng dự án để kết nối một buổi vui chơi có lựa chọn với việc hỗ trợ hiện vật theo nhu cầu thực tế tại Mái ấm Thánh Tâm Xuy Xá.","course":"Học phần SSG105 — Đại học FPT Hà Nội","classId":"AI2015","size":7},"principles":[{"title":"Các em được chọn","description":"Chơi, đổi hoạt động, ngồi xem hay nghỉ đều được tôn trọng; không giao chỉ tiêu hoàn thành sản phẩm cho các em."},{"title":"An toàn trước hết","description":"Vật liệu được kiểm tra an toàn; trò chơi vừa sức; mọi hoạt động tại Mái ấm cần được Mái ấm thống nhất và duyệt trước."},{"title":"Nhóm tự chuẩn bị sản phẩm gây quỹ","description":"Sản phẩm gây quỹ do nhóm chuẩn bị và hoàn thiện. Hoạt động tại Mái ấm hoàn toàn là vui chơi sáng tạo, các em giữ lại sản phẩm do mình làm ra."},{"title":"Minh bạch từng khoản","description":"Thành viên tài chính cùng một thành viên khác đối soát thu chi; tiền và hiện vật ghi riêng; kết quả công khai sau dự án."},{"title":"Giữ riêng tư cho các em","description":"Không dùng hoàn cảnh hay hình ảnh của các em để bán hàng; chỉ đăng ảnh khi được Mái ấm cho phép."}],"areas":[{"title":"Điều phối","members":1,"description":"Lên lịch, theo dõi tiến độ và kết nối các mảng việc của nhóm."},{"title":"Tài chính","members":1,"description":"Giữ sổ thu chi, hóa đơn, đối soát sau mỗi đợt bán và mua quà theo danh mục."},{"title":"Hậu cần và chương trình","members":2,"description":"Chuẩn bị vật tư, đạo cụ, quầy quà lưu niệm và di chuyển cho buổi chơi."},{"title":"Nội dung và truyền thông","members":2,"description":"Thiết kế ấn phẩm, viết bài và lưu trữ hình ảnh đúng phạm vi cho phép."},{"title":"Đối ngoại","members":1,"description":"Làm việc với Mái ấm và các đơn vị hỗ trợ."}],"members":[{"name":"Nguyễn Chí Trung","role":"Trưởng dự án","photo":"/images/thanh-vien/nguyen-chi-trung.webp","description":"Lên lịch, theo dõi tiến độ và điều phối hoạt động của nhóm."},{"name":"Nguyễn Ngọc Khoa","role":"Tài chính","photo":"/images/thanh-vien/nguyen-ngoc-khoa.webp","description":"Giữ sổ ủng hộ, đối chiếu sao kê và mua quà theo danh mục."},{"name":"Nguyễn Như Huy","role":"Hậu cần","photo":"/images/thanh-vien/nguyen-nhu-huy.webp","description":"Chuẩn bị vật tư, đạo cụ và chương trình buổi chơi."},{"name":"Trịnh Hiển Lân","role":"Truyền thông","photo":"/images/thanh-vien/trinh-hien-lan.webp","description":"Viết bài, quản lý lịch đăng và hình ảnh đúng phạm vi cho phép."},{"name":"Trần Bình Trọng","role":"Thiết kế","photo":"/images/thanh-vien/tran-binh-trong.webp","description":"Thiết kế ấn phẩm, poster và nhận diện của dự án."},{"name":"Lê Tuấn Anh","role":"Đối ngoại","photo":"/images/thanh-vien/le-tuan-anh.webp","description":"Làm việc với Mái ấm và các đơn vị hỗ trợ."},{"name":"Nguyễn Anh Khoa","role":"Hậu cần","photo":"/images/thanh-vien/nguyen-anh-khoa.webp","description":"Chuẩn bị quà lưu niệm, quầy và di chuyển."}],"productFaqs":[{"question":"Giá trên trang có phải giá bán chính thức?","answer":"Chưa. Đây là giá tham khảo trong kế hoạch. Giá, mẫu và số lượng chính thức sẽ được công bố khi mở bán."},{"question":"Ai làm các sản phẩm này?","answer":"Toàn bộ sản phẩm gây quỹ do nhóm Lăng Kính chuẩn bị và hoàn thiện. Hoạt động tại Mái ấm hoàn toàn là vui chơi sáng tạo, không gắn với sản xuất hàng bán; các em giữ lại sản phẩm do mình làm ra. Tranh của các em chỉ được in lên móc khóa khi có sự đồng ý phù hợp."},{"question":"Khi nào có thể đặt mua?","answer":"Khi kế hoạch bán được duyệt, nhóm sẽ công bố cách đặt hàng tại trang này. Hiện website chưa nhận đơn đặt hàng hoặc thanh toán sản phẩm."},{"question":"Tiền bán hàng được dùng thế nào?","answer":"Trước hết bù chi phí nguyên liệu và tổ chức. Phần còn lại dùng mua vật phẩm theo danh mục Mái ấm xác nhận, có hóa đơn và biên bản bàn giao."}],"supportFaqs":[{"question":"Làm sao để tên tôi xuất hiện trong sao kê?","answer":"Ghi nội dung chuyển khoản theo mẫu MTMNV và tên bạn muốn hiển thị. Nếu không ghi tên hoặc ghi “An danh”, khoản ủng hộ hiển thị là Ẩn danh. Website không hiển thị số tài khoản hay thông tin ngân hàng của người gửi."},{"question":"Khi nào khoản ủng hộ của tôi được cập nhật?","answer":"Sau mỗi lần thành viên tài chính cùng một thành viên khác đối chiếu với sao kê ngân hàng. Website không kết nối tự động với ngân hàng; khi sổ được công bố, ngày đối soát gần nhất sẽ hiển thị ở đầu bảng. Khoản ủng hộ được cập nhật định kỳ sau khi đối soát xong."},{"question":"Tôi chuyển nhầm số tiền hoặc chuyển trùng thì sao?","answer":"Hãy liên hệ một trong hai số điện thoại của nhóm kèm thời gian và mã giao dịch. Nhóm đối chiếu với sao kê và hoàn lại nếu bạn yêu cầu; khoản đã hoàn không được tính vào tổng ủng hộ."},{"question":"Tiền ủng hộ được dùng vào việc gì?","answer":"Cho vật tư buổi chơi, quà cho các em và di chuyển; phần còn lại mua vật phẩm theo danh mục Mái ấm xác nhận, có hóa đơn và biên bản bàn giao."},{"question":"Tôi có thể cùng đến Mái ấm không?","answer":"Chỉ khi Mái ấm đồng ý trước. Nhóm không tuyển người tự do đến Mái ấm, để bảo đảm an toàn và riêng tư cho các em."}],"transparencyFaqs":[{"question":"Vì sao tổng ủng hộ đang ghi “Chưa cập nhật”?","answer":"Tổng chỉ được tính từ sổ đã đối chiếu với sao kê ngân hàng. Khi nhóm chưa công bố sổ đã đối soát chính thức, website không hiển thị con số (kể cả 0đ) để tránh hiểu lầm là chưa nhận được khoản ủng hộ nào."},{"question":"Tiền bán quà lưu niệm có cộng vào tổng ủng hộ không?","answer":"Không. Thanh tiến độ chỉ tính các khoản ủng hộ qua tài khoản dự án đã đối soát. Tiền bán quà được ghi riêng."},{"question":"Trường hợp số tiền ủng hộ vượt mục tiêu 3.000.000đ thì xử lý thế nào?","answer":"Website vẫn ghi đúng tổng thực tế đã đối soát. Phần vượt mục tiêu sẽ được dùng mua thêm vật phẩm theo danh mục Mái ấm xác nhận và ghi rõ trong báo cáo tổng kết."},{"question":"Khi nào nhóm công bố báo cáo tổng kết dự án?","answer":"Sau buổi trao quà và khi thành viên tài chính cùng một thành viên khác hoàn tất đối soát. Chứng từ chỉ công bố bản đã che thông tin riêng tư."}],"faqs":[{"question":"Giá trên trang có phải giá bán chính thức?","answer":"Chưa. Đây là giá tham khảo trong kế hoạch. Giá, mẫu và số lượng chính thức sẽ được công bố khi mở bán."},{"question":"Ai làm các sản phẩm này?","answer":"Toàn bộ sản phẩm gây quỹ do nhóm Lăng Kính chuẩn bị và hoàn thiện. Hoạt động tại Mái ấm hoàn toàn là vui chơi sáng tạo, các em giữ lại sản phẩm mình làm ra."}],"siteMeta":{"siteTitle":"Mang Theo Một Nét Vẽ | Dự án thiện nguyện sinh viên FPT","siteDescription":"Một buổi chơi phù hợp, một món quà đúng nhu cầu cho các em tại Mái ấm Thánh Tâm Xuy Xá.","ogImage":"/images/illustrations/a01.webp","routeSeo":{}}}', '0d4d1698333deecca2b915c7c2207877d95e2f81976656c8076006b33f11d7a3', 'system-bootstrap@internal', '2026-10-13T00:00:00.000Z');
INSERT OR IGNORE INTO revisions (id, module_key, version, data_json, revision_hash, created_by, created_at, comment) VALUES ('rev-team-1-0d4d1698333d', 'team', 1, '{"info":{"name":"Lăng Kính","description":"Lăng Kính là nhóm gồm 7 sinh viên lớp AI2015, học phần SSG105 (Kỹ năng làm việc nhóm), Đại học FPT Hà Nội. Nhóm xây dựng dự án để kết nối một buổi vui chơi có lựa chọn với việc hỗ trợ hiện vật theo nhu cầu thực tế tại Mái ấm Thánh Tâm Xuy Xá.","course":"Học phần SSG105 — Đại học FPT Hà Nội","classId":"AI2015","size":7},"principles":[{"title":"Các em được chọn","description":"Chơi, đổi hoạt động, ngồi xem hay nghỉ đều được tôn trọng; không giao chỉ tiêu hoàn thành sản phẩm cho các em."},{"title":"An toàn trước hết","description":"Vật liệu được kiểm tra an toàn; trò chơi vừa sức; mọi hoạt động tại Mái ấm cần được Mái ấm thống nhất và duyệt trước."},{"title":"Nhóm tự chuẩn bị sản phẩm gây quỹ","description":"Sản phẩm gây quỹ do nhóm chuẩn bị và hoàn thiện. Hoạt động tại Mái ấm hoàn toàn là vui chơi sáng tạo, các em giữ lại sản phẩm do mình làm ra."},{"title":"Minh bạch từng khoản","description":"Thành viên tài chính cùng một thành viên khác đối soát thu chi; tiền và hiện vật ghi riêng; kết quả công khai sau dự án."},{"title":"Giữ riêng tư cho các em","description":"Không dùng hoàn cảnh hay hình ảnh của các em để bán hàng; chỉ đăng ảnh khi được Mái ấm cho phép."}],"areas":[{"title":"Điều phối","members":1,"description":"Lên lịch, theo dõi tiến độ và kết nối các mảng việc của nhóm."},{"title":"Tài chính","members":1,"description":"Giữ sổ thu chi, hóa đơn, đối soát sau mỗi đợt bán và mua quà theo danh mục."},{"title":"Hậu cần và chương trình","members":2,"description":"Chuẩn bị vật tư, đạo cụ, quầy quà lưu niệm và di chuyển cho buổi chơi."},{"title":"Nội dung và truyền thông","members":2,"description":"Thiết kế ấn phẩm, viết bài và lưu trữ hình ảnh đúng phạm vi cho phép."},{"title":"Đối ngoại","members":1,"description":"Làm việc với Mái ấm và các đơn vị hỗ trợ."}],"members":[{"name":"Nguyễn Chí Trung","role":"Trưởng dự án","photo":"/images/thanh-vien/nguyen-chi-trung.webp","description":"Lên lịch, theo dõi tiến độ và điều phối hoạt động của nhóm."},{"name":"Nguyễn Ngọc Khoa","role":"Tài chính","photo":"/images/thanh-vien/nguyen-ngoc-khoa.webp","description":"Giữ sổ ủng hộ, đối chiếu sao kê và mua quà theo danh mục."},{"name":"Nguyễn Như Huy","role":"Hậu cần","photo":"/images/thanh-vien/nguyen-nhu-huy.webp","description":"Chuẩn bị vật tư, đạo cụ và chương trình buổi chơi."},{"name":"Trịnh Hiển Lân","role":"Truyền thông","photo":"/images/thanh-vien/trinh-hien-lan.webp","description":"Viết bài, quản lý lịch đăng và hình ảnh đúng phạm vi cho phép."},{"name":"Trần Bình Trọng","role":"Thiết kế","photo":"/images/thanh-vien/tran-binh-trong.webp","description":"Thiết kế ấn phẩm, poster và nhận diện của dự án."},{"name":"Lê Tuấn Anh","role":"Đối ngoại","photo":"/images/thanh-vien/le-tuan-anh.webp","description":"Làm việc với Mái ấm và các đơn vị hỗ trợ."},{"name":"Nguyễn Anh Khoa","role":"Hậu cần","photo":"/images/thanh-vien/nguyen-anh-khoa.webp","description":"Chuẩn bị quà lưu niệm, quầy và di chuyển."}],"productFaqs":[{"question":"Giá trên trang có phải giá bán chính thức?","answer":"Chưa. Đây là giá tham khảo trong kế hoạch. Giá, mẫu và số lượng chính thức sẽ được công bố khi mở bán."},{"question":"Ai làm các sản phẩm này?","answer":"Toàn bộ sản phẩm gây quỹ do nhóm Lăng Kính chuẩn bị và hoàn thiện. Hoạt động tại Mái ấm hoàn toàn là vui chơi sáng tạo, không gắn với sản xuất hàng bán; các em giữ lại sản phẩm do mình làm ra. Tranh của các em chỉ được in lên móc khóa khi có sự đồng ý phù hợp."},{"question":"Khi nào có thể đặt mua?","answer":"Khi kế hoạch bán được duyệt, nhóm sẽ công bố cách đặt hàng tại trang này. Hiện website chưa nhận đơn đặt hàng hoặc thanh toán sản phẩm."},{"question":"Tiền bán hàng được dùng thế nào?","answer":"Trước hết bù chi phí nguyên liệu và tổ chức. Phần còn lại dùng mua vật phẩm theo danh mục Mái ấm xác nhận, có hóa đơn và biên bản bàn giao."}],"supportFaqs":[{"question":"Làm sao để tên tôi xuất hiện trong sao kê?","answer":"Ghi nội dung chuyển khoản theo mẫu MTMNV và tên bạn muốn hiển thị. Nếu không ghi tên hoặc ghi “An danh”, khoản ủng hộ hiển thị là Ẩn danh. Website không hiển thị số tài khoản hay thông tin ngân hàng của người gửi."},{"question":"Khi nào khoản ủng hộ của tôi được cập nhật?","answer":"Sau mỗi lần thành viên tài chính cùng một thành viên khác đối chiếu với sao kê ngân hàng. Website không kết nối tự động với ngân hàng; khi sổ được công bố, ngày đối soát gần nhất sẽ hiển thị ở đầu bảng. Khoản ủng hộ được cập nhật định kỳ sau khi đối soát xong."},{"question":"Tôi chuyển nhầm số tiền hoặc chuyển trùng thì sao?","answer":"Hãy liên hệ một trong hai số điện thoại của nhóm kèm thời gian và mã giao dịch. Nhóm đối chiếu với sao kê và hoàn lại nếu bạn yêu cầu; khoản đã hoàn không được tính vào tổng ủng hộ."},{"question":"Tiền ủng hộ được dùng vào việc gì?","answer":"Cho vật tư buổi chơi, quà cho các em và di chuyển; phần còn lại mua vật phẩm theo danh mục Mái ấm xác nhận, có hóa đơn và biên bản bàn giao."},{"question":"Tôi có thể cùng đến Mái ấm không?","answer":"Chỉ khi Mái ấm đồng ý trước. Nhóm không tuyển người tự do đến Mái ấm, để bảo đảm an toàn và riêng tư cho các em."}],"transparencyFaqs":[{"question":"Vì sao tổng ủng hộ đang ghi “Chưa cập nhật”?","answer":"Tổng chỉ được tính từ sổ đã đối chiếu với sao kê ngân hàng. Khi nhóm chưa công bố sổ đã đối soát chính thức, website không hiển thị con số (kể cả 0đ) để tránh hiểu lầm là chưa nhận được khoản ủng hộ nào."},{"question":"Tiền bán quà lưu niệm có cộng vào tổng ủng hộ không?","answer":"Không. Thanh tiến độ chỉ tính các khoản ủng hộ qua tài khoản dự án đã đối soát. Tiền bán quà được ghi riêng."},{"question":"Trường hợp số tiền ủng hộ vượt mục tiêu 3.000.000đ thì xử lý thế nào?","answer":"Website vẫn ghi đúng tổng thực tế đã đối soát. Phần vượt mục tiêu sẽ được dùng mua thêm vật phẩm theo danh mục Mái ấm xác nhận và ghi rõ trong báo cáo tổng kết."},{"question":"Khi nào nhóm công bố báo cáo tổng kết dự án?","answer":"Sau buổi trao quà và khi thành viên tài chính cùng một thành viên khác hoàn tất đối soát. Chứng từ chỉ công bố bản đã che thông tin riêng tư."}],"faqs":[{"question":"Giá trên trang có phải giá bán chính thức?","answer":"Chưa. Đây là giá tham khảo trong kế hoạch. Giá, mẫu và số lượng chính thức sẽ được công bố khi mở bán."},{"question":"Ai làm các sản phẩm này?","answer":"Toàn bộ sản phẩm gây quỹ do nhóm Lăng Kính chuẩn bị và hoàn thiện. Hoạt động tại Mái ấm hoàn toàn là vui chơi sáng tạo, các em giữ lại sản phẩm mình làm ra."}],"siteMeta":{"siteTitle":"Mang Theo Một Nét Vẽ | Dự án thiện nguyện sinh viên FPT","siteDescription":"Một buổi chơi phù hợp, một món quà đúng nhu cầu cho các em tại Mái ấm Thánh Tâm Xuy Xá.","ogImage":"/images/illustrations/a01.webp","routeSeo":{}}}', '0d4d1698333deecca2b915c7c2207877d95e2f81976656c8076006b33f11d7a3', 'system-bootstrap@internal', '2026-10-13T00:00:00.000Z', 'Phiên bản khởi tạo từ nguồn chuẩn tắc (Bootstrap)');

